public sealed interface Customer permits Known, Unknown {}
public record Unknown() implements Customer {}   // the special case, no payload

String name(Customer c) {
    return switch (c) {
        case Known k -> k.name();
        case Unknown u -> "occupant";   // no default: exhaustiveness is checked
    };
}
